    converter.Convert(markdown, html);

    // Apply some basic HTML formatting, depending on your needs
    std::regex italic_regex("\\*([^*]*)\\*");
    std::regex bold_regex("__([^_]+)__");
    std::regex link_regex("\\[([^\\]]+)]\\(([^\\)]+)\\)");
    std::regex header_regex("^#{1,6} ([^#]+)$");

    std::string replaced_markdown = markdown;
    replaced_markdown = std::regex_replace(replaced_markdown, italic_regex, "<em>$1</em>");
    replaced_markdown = std::regex_replace(replaced_markdown, bold_regex, "<strong>$1</strong>");
    replaced_markdown = std::regex_replace(replaced_markdown, link_regex, "<a href=\"$2\">$1</a>");
    std::smatch match;
    while (std::regex_search(replaced_markdown, match, header_regex)) {
        std::string level = std::to_string(match[0].length());
        std::string header_text = match[1];
        replaced_markdown = std::regex_replace(replaced_markdown, match[0], "<h" + level + ">" + header_text + "</h" + level + ">");
    }

    // Replace any remaining Markdown characters with their corresponding HTML entities
    replaced_markdown = std::regex_replace(replaced_markdown, std::regex("\\\\`"), "&#96;");
    replaced_markdown = std::regex_replace(replaced_markdown, std::regex("\\\\*"), "&#42;");
    replaced_markdown = std::regex_replace(replaced_markdown, std::regex("\\\\_"), "&#95;");
    replaced_markdown = std::regex_replace(replaced_markdown, std::regex("\\\\~"), "~");
    replaced_markdown = std::regex_replace(replaced_markdown, std::regex("\\\\|"), "&#124;");
    replaced_markdown = std::regex_replace(replaced_markdown, std::regex("\\\\#"), "&#35;");
    replaced_markdown = std::regex_replace(replaced_markdown, std::regex("\\\\\\"), "\\\\");
    replaced_markdown = std::regex_replace(replaced_markdown, std::regex("\\\\`{3}"), "<pre>");
    replaced_markdown = std::regex_replace(replaced_markdown, std::regex("\\`{3}\\s*\\</pre\\s*>"), "</pre>");
    replaced_markdown = std::regex_replace(replaced_markdown, std::regex("\\\\`{1}"), "`");
    replaced_markdown = std::regex_replace(replaced_markdown, std::regex("\\\\[\\]()"), "[ ](");

    html = replaced_markdown;
    return html;
}

int main() {
    std::string markdown = "Hello **world**! [Google](https://google.com/#q=cpp_markdown) is a #1 search engine.";
    std::string html = convertMarkdownToHtml(markdown);
    std::cout << html << std::endl; // Output: "<p><em>Hello</em> <strong>world</strong>! <a href=\"https://google.com/#q=cpp_markdown\">Google</a> is a <h1>search engine</h1></p>"
    return 0;
}
```

This implementation uses the `cpp_markdown` library to convert the Markdown input to HTML. It then applies some basic formatting, including:

- Italicization: `\*text\*` becomes `<em>text</em>`
- Bold: `__text__` becomes `<strong>text</strong>`
- Links: `[text](url)` becomes `<a href="url">text</a>`
- Headers: `# text` becomes `<h1>text</h1>` (up to 6 hash symbols for headers 1-6)

Finally, it replaces any remaining Markdown characters with their corresponding HTML entities, such as backticks (`\`) and vertical bars (`\|`) to prevent them from being interpreted as Markdown syntax.

Note that this implementation assumes you have a Markdown-to-HTML conversion library available (e.g. `cpp_markdown`, as shown here). If you prefer to implement your own Markdown parser, you'll need to modify this implementation accordingly.

